mapper.insert:
INSERT INTO payments (
reservation_id, user_id, payment_method, payment_key, amount, currency, status,
card_info, bank_info, phone_info, paid_at, created_at, updated_at
) VALUES (
#{reservationId}, #{userId}, #{paymentMethod}, #{paymentKey}, #{amount}, #{currency}, #{status},
#{cardInfo}, #{bankInfo}, #{phoneInfo}, #{paidAt}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE payments
SET status = #{status}, updated_at = #{updatedAt}
WHERE payment_id = #{paymentId}

UPDATE payments
SET status = 'CANCELLED', cancel_reason = #{cancelReason}, cancelled_at = #{cancelledAt}, updated_at = #{cancelledAt}
WHERE payment_id = #{paymentId}

UPDATE payments
SET status = 'FAILED', fail_reason = #{failReason}, updated_at = #{updatedAt}
WHERE payment_id = #{paymentId}

mapper.select:
SELECT p.*, u.username as user_name, a.title as accommodation_title, r.name as room_name
FROM payments p
LEFT JOIN users u ON p.user_id = u.user_id
LEFT JOIN reservations res ON p.reservation_id = res.reservation_id
LEFT JOIN rooms r ON res.room_id = r.room_id
LEFT JOIN accommodations a ON r.accommodation_id = a.accommodation_id


        AND p.user_id = #{userId}


        AND p.reservation_id = #{reservationId}


        AND p.status = #{status}


        AND p.payment_method = #{paymentMethod}


        AND p.created_at >= #{startDate}


        AND p.created_at <= #{endDate}


        AND p.amount >= #{minAmount}


        AND p.amount <= #{maxAmount}


ORDER BY p.created_at DESC

SELECT COUNT(*) as total_count, SUM(amount) as total_amount, SUM(CASE WHEN status = 'COMPLETED' THEN 1 ELSE 0 END) as completed_count, SUM(CASE WHEN status = 'COMPLETED' THEN amount ELSE 0 END) as completed_amount, SUM(CASE WHEN status = 'CANCELLED' THEN 1 ELSE 0 END) as cancelled_count, SUM(CASE WHEN status = 'CANCELLED' THEN amount ELSE 0 END) as cancelled_amount, SUM(CASE WHEN status = 'FAILED' THEN 1 ELSE 0 END) as failed_count, SUM(CASE WHEN payment_method = 'CARD' THEN 1 ELSE 0 END) as card_count, SUM(CASE WHEN payment_method = 'BANK_TRANSFER' THEN 1 ELSE 0 END) as bank_transfer_count, SUM(CASE WHEN payment_method = 'PHONE' THEN 1 ELSE 0 END) as phone_count FROM payments
AND created_at >= #{startDate}
AND created_at <= #{endDate}
